SELECT order_id, product_id, CASE WHEN unit_price >= 350 THEN 'high' WHEN unit_price >= 90 THEN 'mid' ELSE 'low' END AS unit_price_bucket, COUNT(quantity) AS quantity_count, SUM(quantity * unit_price) AS revenue FROM order_items WHERE quantity <= 6 AND order_id IN (4, 10, 17, 26) GROUP BY order_id, product_id, CASE WHEN unit_price >= 350 THEN 'high' WHEN unit_price >= 90 THEN 'mid' ELSE 'low' END
